INSERT INTO grades (grade_id, grade_number, name_hi, name_target, name_en) VALUES ('G2', '2', 'कक्षा 2', 'ᱠᱞᱟᱥ 2', 'Grade 2');
INSERT INTO subjects (subject_id, grade_id, name_hi, name_target, name_en) VALUES ('SUBJ-MATH-G2', 'G2', 'गणित', 'ᱮᱞᱮᱠᱷ ᱥᱟᱧᱟ', 'Mathematics');
INSERT INTO chapters (chapter_id, subject_id, name_hi, name_target, name_en, sequence) VALUES ('CH-COUNT-G2', 'SUBJ-MATH-G2', 'गिनती', 'ᱞᱮᱠᱷᱟ', 'Counting', '1');
INSERT INTO lessons (lesson_id, chapter_id, title_hi, title_target, title_en, sequence, estimated_minutes) VALUES ('L-COUNT-G2', 'CH-COUNT-G2', 'वस्तुओं और संख्याओं की गिनती (1 से 100)', 'ᱡᱤᱱᱤᱥ ᱟᱨ ᱞᱮᱠᱷᱟ ᱞᱮᱠᱷᱟ (᱑ ᱠᱷᱚᱱ ᱑᱐᱐)', 'Counting Objects and Numbers (1 to 100)', '1', '40');
INSERT INTO learning_outcomes (outcome_id, lesson_id, code, description_hi, description_target, description_en, sequence) VALUES ('LO-COUNT-1', 'L-COUNT-G2', 'G2-M-CNT-01', 'छात्र 20 तक की वस्तुओं को एक-एक करके ठीक से गिन सकेंगे।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱒᱐ ᱫᱷᱟᱹᱵᱤᱡ ᱡᱤᱱᱤᱥ ᱢᱤᱫ ᱢᱤᱫ ᱛᱮ ᱡᱚᱛᱚᱱ ᱞᱮᱠᱷᱟ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ ᱾', 'Student can count objects up to 20 accurately, one by one.', '1');
INSERT INTO learning_outcomes (outcome_id, lesson_id, code, description_hi, description_target, description_en, sequence) VALUES ('LO-COUNT-2', 'L-COUNT-G2', 'G2-M-CNT-02', 'छात्र 1 से 100 तक की संख्याएँ पढ़ और लिख सकेंगे।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱑ ᱠᱷᱚᱱ ᱑᱐᱐ ᱫᱷᱟᱹᱵᱤᱡ ᱞᱮᱠᱷᱟ ᱯᱟᱲᱦᱟᱣ ᱟᱨ ᱚᱞ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ ᱾', 'Student can read and write numbers from 1 to 100.', '2');
INSERT INTO learning_outcomes (outcome_id, lesson_id, code, description_hi, description_target, description_en, sequence) VALUES ('LO-COUNT-3', 'L-COUNT-G2', 'G2-M-CNT-03', 'छात्र 2, 5 और 10 के स्टेप में गिन सकेंगे (छलांग गिनती)।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱒, ᱕ ᱟᱨ ᱑᱐ ᱛᱮ ᱞᱮᱠᱷᱟ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ (ᱡᱟᱸᱯ ᱞᱮᱠᱷᱟ) ᱾', 'Student can skip-count by 2, 5 and 10.', '3');
INSERT INTO learning_outcomes (outcome_id, lesson_id, code, description_hi, description_target, description_en, sequence) VALUES ('LO-COUNT-4', 'L-COUNT-G2', 'G2-M-CNT-04', 'छात्र किसी संख्या से पहले, बाद और बीच की संख्या बता सकेंगे।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱢᱤᱫ ᱞᱮᱠᱷᱟ ᱠᱷᱚᱱ ᱟᱨᱡᱚ, ᱛᱟᱭᱚᱢ ᱟᱨ ᱛᱟᱞᱟ ᱨᱮᱭᱟᱜ ᱞᱮᱠᱷᱟ ᱞᱟᱹᱭ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ ᱾', 'Student can state the number before, after and between a given number.', '4');
INSERT INTO learning_outcomes (outcome_id, lesson_id, code, description_hi, description_target, description_en, sequence) VALUES ('LO-COUNT-5', 'L-COUNT-G2', 'G2-M-CNT-05', 'छात्र दो संख्याओं में बड़ी और छोटी संख्या पहचान सकेंगे।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱵᱟᱨᱭᱟ ᱞᱮᱠᱷᱟ ᱠᱷᱚᱱ ᱢᱟᱨᱟᱝ ᱟᱨ ᱦᱟᱢᱟᱞ ᱞᱮᱠᱷᱟ ᱪᱤᱱᱦᱟᱹ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ ᱾', 'Student can identify the greater and smaller of two numbers.', '5');
INSERT INTO teacher_instructions (instruction_id, lesson_id, text_hi, text_target, text_en, sequence) VALUES ('TI-COUNT-1', 'L-COUNT-G2', 'सबसे पहले छात्रों को वास्तविक वस्तुओं (मिट्टी के बर्तन, पेन्सिल) से गिनना सिखाएं। गिनती के समय छात्रों को आवाज़ में गिनने के लिए प्रोत्साहित करें।', 'ᱟᱹᱢᱟᱹᱞᱤ ᱯᱟᱹᱴᱷᱣᱟᱹ ᱠᱚᱭ ᱟᱥᱚᱞ ᱡᱤᱱᱤᱥ (ᱠᱷᱟᱫᱟᱱ ᱵᱚᱨᱛᱚᱱ, ᱯᱮᱱᱥᱤᱞ) ᱛᱮ ᱞᱮᱠᱷᱟ ᱯᱟᱲᱦᱟᱣ ᱢᱟᱲᱟᱝ ᱠᱟᱹᱢᱤ ᱦᱚᱪᱚᱭ ᱢᱟ। ᱞᱮᱠᱷᱟ ᱚᱠᱛᱚ ᱯᱟᱹᱴᱷᱣᱟᱹ ᱠᱚ ᱟᱲᱟᱝ ᱛᱮ ᱞᱮᱠᱷᱟ ᱞᱟᱹᱜᱤᱫ ᱦᱩᱥᱟᱹᱨ ᱦᱚᱪᱚᱭ ᱢᱟ।', 'First teach counting with real objects (clay pots, pencils). Encourage students to count aloud.', '1');
INSERT INTO teacher_instructions (instruction_id, lesson_id, text_hi, text_target, text_en, sequence) VALUES ('TI-COUNT-2', 'L-COUNT-G2', 'गिनती के बाद छात्रों को संख्या लिखने का अभ्यास कराएं। गलती होने पर सुधारें, डांटें नहीं।', 'ᱞᱮᱠᱷᱟ ᱛᱟᱭᱚᱢ ᱯᱟᱹᱴᱷᱣᱟᱹ ᱠᱚᱭ ᱞᱮᱠᱷᱟ ᱚᱞ ᱞᱟᱹᱜᱤᱫ ᱪᱟᱹᱞᱤ ᱦᱚᱪᱚᱭ ᱢᱟ। ᱵᱷᱟᱹᱲ ᱦᱩᱭ ᱞᱮᱱ ᱠᱷᱟᱱ ᱥᱚᱫᱚᱥ ᱢᱟ, ᱵᱚᱛᱚᱨ ᱢᱤᱫ ᱢᱤᱫ ᱛᱮ ᱵᱟᱭ ᱢᱟ।', 'After counting, have students practice writing numbers. Correct mistakes gently, do not scold.', '2');
INSERT INTO activities (activity_id, outcome_id, title_hi, title_target, title_en, activity_type, instructions_hi, instructions_target, instructions_en, sequence) VALUES ('ACT-COUNT-1A', 'LO-COUNT-1', 'मेज़ पर 20 तक गिनती', 'ᱴᱮᱵᱚᱞ ᱪᱮᱛᱟᱱ ᱒᱐ ᱫᱷᱟᱹᱵᱤᱡ ᱞᱮᱠᱷᱟ', 'Count to 20 on the table', 'hands_on', 'मेज़ पर 20 कंचे रखें। छात्र एक-एक करके गिने और आवाज़ में बोले।', 'ᱴᱮᱵᱚᱞ ᱪᱮᱛᱟᱱ ᱒᱐ ᱜᱚᱴᱟᱝ ᱜᱩᱴᱤ ᱫᱚᱦᱚ ᱢᱟ। ᱯᱟᱹᱴᱷᱣᱟᱹ ᱢᱤᱫ ᱢᱤᱫ ᱛᱮ ᱞᱮᱠᱷᱟ ᱟᱨ ᱟᱲᱟᱝ ᱛᱮ ᱞᱟᱹᱭ ᱢᱟ।', 'Place 20 marbles on the table. Students count one by one and say aloud.', '1');
INSERT INTO activities (activity_id, outcome_id, title_hi, title_target, title_en, activity_type, instructions_hi, instructions_target, instructions_en, sequence) VALUES ('ACT-COUNT-2A', 'LO-COUNT-2', 'संख्या पहेली कार्ड', 'ᱞᱮᱠᱷᱟ ᱯᱟᱧᱡᱤ ᱠᱟᱨᱰ', 'Number puzzle cards', 'individual_practice', 'छात्रों को 1 से 50 तक के कार्ड सही क्रम में लगाने हैं।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱠᱚ ᱑ ᱠᱷᱚᱱ ᱕᱐ ᱫᱷᱟᱹᱵᱤᱡ ᱠᱟᱨᱰ ᱡᱚᱛᱚᱱ ᱦᱚᱨᱚᱜ ᱨᱮ ᱫᱚᱦᱚ ᱦᱩᱭᱟᱜ-ᱟ।', 'Students arrange cards 1 to 50 in correct order.', '1');
INSERT INTO activities (activity_id, outcome_id, title_hi, title_target, title_en, activity_type, instructions_hi, instructions_target, instructions_en, sequence) VALUES ('ACT-COUNT-3A', 'LO-COUNT-3', 'छलांग गिनती गेम', 'ᱡᱟᱸᱯ ᱞᱮᱠᱷᱟ ᱠᱷᱮᱞ', 'Skip-count game', 'group_game', 'गोले में खड़े होकर 2-2 करके गिनें: 2, 4, 6...। फिर 5-5 और 10-10।', 'ᱜᱚᱞ ᱛᱮ ᱡᱤᱞᱤᱫ ᱠᱟᱛᱮ ᱒-᱒ ᱛᱮ ᱞᱮᱠᱷᱟ: ᱒, ᱔, ᱖...। ᱛᱟᱭᱚᱢ ᱕-᱕ ᱟᱨ ᱑᱐-᱑᱐ ᱛᱮ।', 'Stand in a circle and skip-count by 2: 2,4,6... Then by 5 and 10.', '1');
INSERT INTO activities (activity_id, outcome_id, title_hi, title_target, title_en, activity_type, instructions_hi, instructions_target, instructions_en, sequence) VALUES ('ACT-COUNT-4A', 'LO-COUNT-4', 'पहले-बाद-बीच का खेल', 'ᱟᱨᱡᱚ-ᱛᱟᱭᱚᱢ-ᱛᱟᱞᱟ ᱮᱱᱮᱡ', 'Before-after-between game', 'pair_work', 'एक छात्र संख्या बोलता है, दूसरा उससे पहले और बाद वाली संख्या बताता है।', 'ᱢᱤᱫ ᱯᱟᱹᱴᱷᱣᱟᱹ ᱞᱮᱠᱷᱟ ᱞᱟᱹᱭ ᱢᱟ, ᱫᱚᱥᱟᱨ ᱦᱚᱲ ᱚᱱᱟ ᱠᱷᱚᱱ ᱟᱨᱡᱚ ᱟᱨ ᱛᱟᱭᱚᱢ ᱨᱮᱭᱟᱜ ᱞᱮᱠᱷᱟ ᱞᱟᱹᱭ ᱢᱟ।', 'One student says a number; the other states the one before and after.', '1');
INSERT INTO activities (activity_id, outcome_id, title_hi, title_target, title_en, activity_type, instructions_hi, instructions_target, instructions_en, sequence) VALUES ('ACT-COUNT-5A', 'LO-COUNT-5', 'बड़ा-छोटा चुनो', 'ᱢᱟᱨᱟᱝ-ᱦᱟᱢᱟᱞ ᱵᱟᱪᱷᱟᱣ', 'Pick greater-smaller', 'pair_work', 'दो कार्ड दिखाएं; छात्र बताए कौन बड़ा है।', 'ᱵᱟᱨᱭᱟ ᱠᱟᱨᱰ ᱩᱫᱩᱜ ᱢᱟ; ᱯᱟᱹᱴᱷᱣᱟᱹ ᱞᱟᱹᱭ ᱢᱟ ᱟᱱᱟᱜ ᱫᱚ ᱢᱟᱨᱟᱝ ᱠᱟᱱᱟ।', 'Show two cards; student says which is greater.', '1');
INSERT INTO assessments (assessment_id, outcome_id, type, prompt_hi, prompt_target, prompt_en, answer_key, difficulty, sequence) VALUES ('AS-COUNT-1', 'LO-COUNT-1', 'observation', 'छात्र को 15 कंचे गिनकर दिखाने हैं।', 'ᱯᱟᱹᱴᱷᱣᱟᱹ ᱑᱕ ᱜᱚᱴᱟᱝ ᱜᱩᱴᱤ ᱞᱮᱠᱷᱟ ᱠᱟᱛᱮ ᱩᱫᱩᱜ ᱦᱩᱭᱟᱜ-ᱟ।', 'Student must count and show 15 marbles.', 'Correct oral/physical count to 15 with no skipped objects.', 'easy', '1');
INSERT INTO assessments (assessment_id, outcome_id, type, prompt_hi, prompt_target, prompt_en, answer_key, difficulty, sequence) VALUES ('AS-COUNT-2', 'LO-COUNT-2', 'written', 'रिक्त स्थान भरें: 47 के बाद ____ आता है।', 'ᱫᱟᱹᱵᱤ ᱯᱩᱨᱟᱹᱣ: ᱔᱗ ᱛᱟᱭᱚᱢ ____ ᱦᱤᱡᱩᱜ-ᱟ।', 'Fill the blank: after 47 comes ____.', '48', 'easy', '1');
INSERT INTO assessments (assessment_id, outcome_id, type, prompt_hi, prompt_target, prompt_en, answer_key, difficulty, sequence) VALUES ('AS-COUNT-3', 'LO-COUNT-3', 'oral', '5-5 करके गिनें: 5, 10, __, __, 25।', '᱕-᱕ ᱛᱮ ᱞᱮᱠᱷᱟ: ᱕, ᱑᱐, __, __, ᱒᱕।', 'Skip-count by 5: 5, 10, __, __, 25.', '15, 20', 'medium', '1');
INSERT INTO assessments (assessment_id, outcome_id, type, prompt_hi, prompt_target, prompt_en, answer_key, difficulty, sequence) VALUES ('AS-COUNT-4', 'LO-COUNT-4', 'written', '39 और 41 के बीच कौन सी संख्या है?', '᱓᱙ ᱟᱨ ᱔᱑ ᱛᱟᱞᱟ ᱨᱮ ᱟᱱᱟᱜ ᱞᱮᱠᱷᱟ ᱠᱟᱱᱟ?', 'Which number is between 39 and 41?', '40', 'easy', '1');
INSERT INTO assessments (assessment_id, outcome_id, type, prompt_hi, prompt_target, prompt_en, answer_key, difficulty, sequence) VALUES ('AS-COUNT-5', 'LO-COUNT-5', 'written', 'इन दो संख्याओं में बड़ी कौन है: 63 या 36?', 'ᱵᱟᱨᱭᱟ ᱞᱮᱠᱷᱟ ᱠᱷᱚᱱ ᱢᱟᱨᱟᱝ ᱟᱱᱟᱜ ᱠᱟᱱᱟ: ᱖᱓ ᱱᱚᱝᱠᱟ ᱓᱖?', 'Which is greater: 63 or 36?', '63', 'easy', '1');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-1', 'L-COUNT-G2', 'गिनती', 'ᱞᱮᱠᱷᱟ', 'counting', 'वस्तुओं को एक-एक कर गिनना।', 'ᱡᱤᱱᱤᱥ ᱢᱤᱫ ᱢᱤᱫ ᱛᱮ ᱞᱮᱠᱷᱟ ᱠᱟᱛᱮ ᱞᱮᱠᱷᱟ ᱾', 'Counting objects one by one.');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-2', 'L-COUNT-G2', 'संख्या', 'ᱞᱮᱠᱷᱟ', 'number', 'गिनती का नाम (जैसे ५)।', 'ᱞᱮᱠᱷᱟ ᱨᱮᱭᱟᱜ ᱧᱩᱛᱩᱢ (ᱡᱮᱞᱮᱠᱟ ᱕)।', 'Name of a count (e.g. 5).');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-3', 'L-COUNT-G2', 'अधिक', 'ᱵᱟᱹᱲᱛᱤ', 'more', 'संख्या बड़ी होना।', 'ᱞᱮᱠᱷᱟ ᱢᱟᱨᱟᱝ ᱦᱩᱭᱩᱜ ᱾', 'Greater in quantity.');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-4', 'L-COUNT-G2', 'कम', 'ᱠᱚᱢ', 'less', 'संख्या छोटी होना।', 'ᱞᱮᱠᱷᱟ ᱦᱟᱢᱟᱞ ᱦᱩᱭᱩᱜ ᱾', 'Smaller in quantity.');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-5', 'L-COUNT-G2', 'दहाई', 'ᱜᱮᱞ', 'ten', '10 की संख्या।', '᱑᱐ ᱞᱮᱠᱷᱟ ᱾', 'The number 10.');
INSERT INTO vocabulary_terms (term_id, lesson_id, term_hi, term_target, term_en, definition_hi, definition_target, definition_en) VALUES ('VOC-COUNT-6', 'L-COUNT-G2', 'सौ', 'ᱥᱟᱭ', 'hundred', '100 की संख्या।', '᱑᱐᱐ ᱞᱮᱠᱷᱟ ᱾', 'The number 100.');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-1', 'L-COUNT-G2', '१', '᱑', '1', 'assets/flashcards/number_1.png', 'assets/audio/sat/number_1.wav', '1');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-2', 'L-COUNT-G2', '२', '᱒', '2', 'assets/flashcards/number_2.png', 'assets/audio/sat/number_2.wav', '2');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-3', 'L-COUNT-G2', '३', '᱓', '3', 'assets/flashcards/number_3.png', 'assets/audio/sat/number_3.wav', '3');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-4', 'L-COUNT-G2', '४', '᱔', '4', 'assets/flashcards/number_4.png', 'assets/audio/sat/number_4.wav', '4');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-5', 'L-COUNT-G2', '५', '᱕', '5', 'assets/flashcards/number_5.png', 'assets/audio/sat/number_5.wav', '5');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-6', 'L-COUNT-G2', '६', '᱖', '6', 'assets/flashcards/number_6.png', 'assets/audio/sat/number_6.wav', '6');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-7', 'L-COUNT-G2', '७', '᱗', '7', 'assets/flashcards/number_7.png', 'assets/audio/sat/number_7.wav', '7');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-8', 'L-COUNT-G2', '८', '᱘', '8', 'assets/flashcards/number_8.png', 'assets/audio/sat/number_8.wav', '8');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-9', 'L-COUNT-G2', '९', '᱙', '9', 'assets/flashcards/number_9.png', 'assets/audio/sat/number_9.wav', '9');
INSERT INTO flashcard_concepts (card_id, lesson_id, concept_hi, concept_target, concept_en, image_ref, audio_ref, sequence) VALUES ('FC-10', 'L-COUNT-G2', '१०', '᱑᱐', '10', 'assets/flashcards/number_10.png', 'assets/audio/sat/number_10.wav', '10');
